.ds-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 36px;
  padding: 0 16px;
  border: 0;
  border-radius: 6px;
  font-family: Inter, system-ui, sans-serif;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.45;
  white-space: nowrap;
  cursor: pointer;
  transition: color 120ms cubic-bezier(0.2, 0, 0, 1),
              background-color 120ms cubic-bezier(0.2, 0, 0, 1),
              border-color 120ms cubic-bezier(0.2, 0, 0, 1),
              scale 120ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-btn:active { scale: 0.96; }
.ds-btn:focus-visible { outline: 2px solid hsl(var(--ring)); outline-offset: 2px; }
.ds-btn svg { width: 16px; height: 16px; flex: none; }

.ds-btn--primary {
  background-color: hsl(var(--primary));
  color: hsl(var(--primary-foreground));
  box-shadow: 0px 2px 4px 0px hsl(0 0% 0% / 0.1), 0px 1px 2px -1px hsl(0 0% 0% / 0.1);
}
.ds-btn--primary:hover { background-color: hsl(var(--button-hover)); }

@media (prefers-reduced-motion: reduce) {
  .ds-btn { transition: none; }
  .ds-btn:active { scale: 1; }
}

.ds-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 36px;
  padding: 0 16px;
  border: 0;
  border-radius: 6px;
  background-color: hsl(var(--button-secondary));
  color: hsl(var(--button-secondary-foreground));
  font-family: Inter, system-ui, sans-serif;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.45;
  cursor: pointer;
  box-shadow: 0px 2px 4px 0px hsl(0 0% 0% / 0.05);
  transition: background-color 120ms cubic-bezier(0.2, 0, 0, 1), scale 120ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-btn-secondary:hover { background-color: hsl(var(--button-secondary-hover)); }
.ds-btn-secondary:active { scale: 0.96; }
.ds-btn-secondary:focus-visible { outline: 2px solid hsl(var(--ring)); outline-offset: 2px; }

@media (prefers-reduced-motion: reduce) {
  .ds-btn-secondary { transition: none; }
  .ds-btn-secondary:active { scale: 1; }
}

.ds-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border: 1px solid hsl(var(--input-border));
  border-radius: 6px;
  background-color: hsl(var(--background));
  color: hsl(var(--foreground));
  cursor: pointer;
  box-shadow: 0px 2px 4px 0px hsl(0 0% 0% / 0.05);
  transition: background-color 120ms cubic-bezier(0.2, 0, 0, 1),
              color 120ms cubic-bezier(0.2, 0, 0, 1),
              border-color 120ms cubic-bezier(0.2, 0, 0, 1),
              scale 120ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-icon-btn svg { width: 16px; height: 16px; }
.ds-icon-btn:hover { background-color: hsl(var(--hover)); color: hsl(var(--hover-foreground)); }
.ds-icon-btn:active { scale: 0.96; }
.ds-icon-btn:focus-visible { outline: 2px solid hsl(var(--ring)); outline-offset: 2px; }

@media (prefers-reduced-motion: reduce) {
  .ds-icon-btn { transition: none; }
  .ds-icon-btn:active { scale: 1; }
}

.ds-field { display: flex; flex-direction: column; gap: 4px; font-family: Inter, system-ui, sans-serif; }
.ds-field__label { font-size: 12px; font-weight: 500; line-height: 1.4; color: hsl(var(--foreground)); }
.ds-field__input {
  height: 36px;
  width: 100%;
  box-sizing: border-box;
  padding: 0 12px;
  border: 1px solid hsl(var(--input-border));
  border-radius: 6px;
  background-color: hsl(var(--input-field));
  color: hsl(var(--input-foreground));
  font: inherit;
  font-size: 14px;
  box-shadow: 0px 2px 4px 0px hsl(0 0% 0% / 0.05);
  transition: border-color 120ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-field__input::placeholder { color: hsl(var(--input-placeholder)); }
.ds-field__input:hover { border-color: hsl(var(--muted-foreground)); }
.ds-field__input:focus-visible { outline: 2px solid hsl(var(--ring)); outline-offset: -1px; border-color: hsl(var(--ring)); }
.ds-field__input:disabled { background-color: hsl(var(--muted)); color: hsl(var(--muted-foreground)); cursor: not-allowed; }

@media (prefers-reduced-motion: reduce) {
  .ds-field__input { transition: none; }
}

.ds-composer {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px 8px;
  border: 1px solid hsl(var(--foreground) / 0.10);
  border-radius: 12px;
  background-color: hsl(var(--background));
  font-family: Inter, system-ui, sans-serif;
  transition: border-color 150ms cubic-bezier(0.2, 0, 0, 1);
}
.dark .ds-composer { border-color: hsl(var(--input-border) / 0.7); }
.ds-composer:focus-within { border-color: hsl(var(--ring) / 0.4); }
.ds-composer__input {
  padding: 0 4px;
  min-height: 48px;
  border: 0;
  background: transparent;
  color: hsl(var(--input-foreground));
  font: inherit;
  font-size: 14px;
  line-height: 24px;
  resize: none;
}
.ds-composer__input::placeholder { color: hsl(var(--input-placeholder)); }
.ds-composer__input:focus { outline: none; }
.ds-composer__toolbar { display: flex; align-items: center; gap: 8px; padding-top: 2px; }
.ds-composer__attach {
  display: inline-flex; align-items: center; justify-content: center;
  width: 28px; height: 28px; padding: 0;
  border: 0; border-radius: 6px; background: transparent;
  color: hsl(var(--muted-foreground)); cursor: pointer;
  transition: color 120ms cubic-bezier(0.2, 0, 0, 1), background-color 120ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-composer__attach svg { width: 16px; height: 16px; }
.ds-composer__attach:hover { background-color: hsl(var(--hover)); color: hsl(var(--foreground)); }
.ds-composer__send {
  display: inline-flex; align-items: center; justify-content: center;
  width: 28px; height: 28px; padding: 0;
  margin-inline-start: auto;
  border: 0; border-radius: 999px;
  background-color: hsl(var(--foreground)); color: hsl(var(--background));
  cursor: pointer;
  transition: background-color 100ms cubic-bezier(0.2, 0, 0, 1), scale 100ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-composer__send svg { width: 16px; height: 16px; }
.ds-composer__send:hover { background-color: hsl(var(--foreground) / 0.85); }
.ds-composer__send:active { scale: 0.96; }
.ds-composer__send:focus-visible,
.ds-composer__attach:focus-visible { outline: 2px solid hsl(var(--ring)); outline-offset: 2px; }

@media (prefers-reduced-motion: reduce) {
  .ds-composer, .ds-composer__attach, .ds-composer__send { transition: none; }
  .ds-composer__send:active { scale: 1; }
}

.ds-row {
  display: flex;
  align-items: center;
  gap: 4px;
  height: 28px;
  padding-inline-end: 8px;
  font-family: Inter, system-ui, sans-serif;
}
.ds-row__label {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1 1 auto;
  min-width: 0;
  height: 28px;
  padding: 0 8px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: hsl(var(--sidebar-foreground));
  font: inherit;
  font-size: 14px;
  text-align: start;
  cursor: pointer;
  transition: color 120ms cubic-bezier(0.2, 0, 0, 1), background-color 120ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-row__label:hover { background-color: hsl(var(--sidebar-hover)); color: hsl(var(--sidebar-hover-foreground)); }
.ds-row__label:focus-visible { outline: 2px solid hsl(var(--sidebar-ring)); outline-offset: -1px; }
.ds-row__name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-row__chevron, .ds-row__icon { width: 14px; height: 14px; flex: none; color: hsl(var(--sidebar-foreground-muted)); }

.ds-row__action {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: hsl(var(--muted-foreground));
  opacity: 0;
  pointer-events: none;
  cursor: pointer;
  transition: opacity 100ms cubic-bezier(0.2, 0, 0, 1), color 100ms cubic-bezier(0.2, 0, 0, 1), background-color 100ms cubic-bezier(0.2, 0, 0, 1);
}
/* drawn at 20x20, hit area 24x24 - the Whole-Pixel Hit Area Rule */
.ds-row__action::after { content: ""; position: absolute; inset: -2px; }
.ds-row__action svg { width: 14px; height: 14px; }
.ds-row:hover .ds-row__action,
.ds-row__action:focus-visible { opacity: 1; pointer-events: auto; }
.ds-row__action:hover { color: hsl(var(--foreground)); background-color: hsl(var(--muted)); }
.ds-row__action:focus-visible { outline: 2px solid hsl(var(--sidebar-ring)); outline-offset: 2px; }

@media (prefers-reduced-motion: reduce) {
  .ds-row__label, .ds-row__action { transition: none; }
}

.ds-chip-set { display: flex; align-items: center; gap: 8px; }
.ds-chip {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 10px;
  border: 1px solid transparent;
  border-radius: 6px;
  font-family: Inter, system-ui, sans-serif;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.4;
  white-space: nowrap;
  box-shadow: 0px 2px 4px 0px hsl(0 0% 0% / 0.05);
}
.ds-chip--running { background-color: hsl(var(--primary)); color: hsl(var(--primary-foreground)); }
.ds-chip--success {
  border-color: hsl(var(--status-success) / 0.20);
  background-color: hsl(var(--status-success) / 0.12);
  color: hsl(var(--status-success));
}
.ds-chip--warning {
  border-color: hsl(var(--status-warning) / 0.20);
  background-color: hsl(var(--status-warning) / 0.12);
  color: hsl(var(--status-warning));
}

.ds-card {
  border: 1px solid hsl(var(--border));
  border-radius: 8px;
  background-color: hsl(var(--card));
  color: hsl(var(--card-foreground));
  font-family: Inter, system-ui, sans-serif;
  box-shadow: 0px 2px 4px 0px hsl(0 0% 0% / 0.05);
}
.ds-card__header { display: flex; flex-direction: column; gap: 6px; padding: 24px; }
.ds-card__title { margin: 0; font-size: 24px; font-weight: 600; line-height: 1.25; letter-spacing: -0.025em; color: hsl(var(--foreground)); }
.ds-card__description { margin: 0; font-size: 14px; line-height: 1.45; color: hsl(var(--muted-foreground)); }
.ds-card__body { padding: 0 24px 24px; }
.ds-card__value { font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 12px; line-height: 1.5; color: hsl(var(--code-foreground)); }

.ds-menu {
  min-width: 220px;
  padding: 4px;
  border-radius: 12px;
  background-color: hsl(var(--background));
  color: hsl(var(--foreground));
  font-family: Inter, system-ui, sans-serif;
  /* edge is the ring in the stack, not a border - no layout box, theme-derived color */
  box-shadow: 0 0 0 1px color-mix(in oklab, hsl(var(--background)) 90%, hsl(var(--foreground)) 10%),
              0 4px 12px 0 rgb(0 0 0 / 0.08),
              0 1px 3px 0 rgb(0 0 0 / 0.06);
}
.ds-menu__label { padding: 6px 12px; font-size: 12px; font-weight: 500; line-height: 1.4; color: hsl(var(--muted-foreground)); }
.ds-menu__item {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 32px;
  padding: 6px 12px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: hsl(var(--foreground));
  font: inherit;
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
  text-align: start;
  cursor: default;
  transition: color 120ms cubic-bezier(0.2, 0, 0, 1), background-color 120ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-menu__icon { display: flex; align-items: center; justify-content: center; width: 14px; height: 14px; flex: none; color: hsl(var(--muted-foreground)); }
.ds-menu__icon svg { width: 100%; height: 100%; }
.ds-menu__extra { margin-inline-start: auto; padding-inline-start: 16px; font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 12px; color: hsl(var(--muted-foreground)); }
.ds-menu__item:hover, .ds-menu__item:focus-visible { background-color: hsl(var(--hover)); color: hsl(var(--hover-foreground)); outline: none; }
.ds-menu__item[data-variant="destructive"] { color: hsl(var(--destructive)); }
.ds-menu__item[data-variant="destructive"] .ds-menu__icon { color: hsl(var(--destructive)); }
.ds-menu__item[data-variant="destructive"]:hover,
.ds-menu__item[data-variant="destructive"]:focus-visible { background-color: hsl(var(--destructive) / 0.10); color: hsl(var(--destructive)); }

@media (prefers-reduced-motion: reduce) { .ds-menu__item { transition: none; } }
